ci.yml.plan:
  name: plan
  runs-on: ubuntu-latest
  timeout-minutes: 5
  outputs:
    tier: ${{ steps.plan.outputs.tier }}
    jobs: ${{ steps.plan.outputs.jobs }}
    matrix_test: ${{ steps.plan.outputs.matrix_test }}
    matrix_nvim_plugin: ${{ steps.plan.outputs.matrix_nvim_plugin }}
    matrix_vscode_extension: ${{ steps.plan.outputs.matrix_vscode_extension }}
    matrix_server_lane: ${{ steps.plan.outputs.matrix_server_lane }}
    matrix_helix_config: ${{ steps.plan.outputs.matrix_helix_config }}
    matrix_emacs_mode: ${{ steps.plan.outputs.matrix_emacs_mode }}
  steps:
    # Depth 2: a pull request's run checks out its merge commit, and the
    # plan reads that commit against its first parent. A dispatch reads
    # its branch against trunk's merge base, so it takes the history.
    - uses: actions/checkout@v5
      with:
        fetch-depth: ${{ github.event_name == 'workflow_dispatch' && '0' || '2' }}
    - name: the planner can say no (ci/tiers-test.py)
      run: python3 ci/tiers-test.py
    - name: the plan
      id: plan
      env:
        EVENT: ${{ github.event_name }}
        ACTION: ${{ github.event.action }}
        LABEL: ${{ github.event.label.name }}
        LABELS: ${{ join(github.event.pull_request.labels.*.name, ',') }}
        HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        IN_TIER: ${{ inputs.tier }}
      run: python3 ci/tiers.py plan --merge --github-output "$GITHUB_OUTPUT"

# The server-free gate, on the full D35 tier-1 host set.
